type Money = number;
type TabId = 'today' | 'newOrder' | 'stock' | 'alerts';
type StockStatus = 'green' | 'amber' | 'red';

interface Product {
  id: string;
  name: string;
  priceDisplayedPence: Money;
  stockOnHand: number;
  reorderLevel: number;
}

interface OrderLine {
  productId: string;
  quantity: number;
  unitPricePence: Money;
}

interface Customer {
  id: string;
  name: string;
  phone: string;
}

interface Order {
  id: string;
  lines: OrderLine[];
  customer: Customer;
  fulfilmentDate: string;
  status: string;
  totalPence: Money;
  createdAt: string;
  pending: boolean;
}

interface StockMovement {
  id: string;
  productId: string;
  quantity: number;
  reason: string;
  createdAt: string;
  pending: boolean;
}

interface LocalSnapshot {
  products: Product[];
  orders: Order[];
  movements: StockMovement[];
  pending: boolean;
  syncedAt: string;
}

interface LowStockAlert {
  productId: string;
  productName: string;
  stockOnHand: number;
  reorderLevel: number;
  suggestedQuantity: number;
  createdAt: string;
  reordered: boolean;
  note: string;
}

const DEFAULT_FULFILMENT_DATE: string = 'today';
const GBP_PREFIX: string = '£';

function localDb(): { products: Product[]; orders: Order[]; movements: StockMovement[]; alerts: LowStockAlert[]; syncedAt: string; pending: boolean } {
  return {
    products: [],
    orders: [],
    movements: [],
    alerts: [],
    syncedAt: '',
    pending: false,
  };
}

/**
 * Reads the local snapshot of products, orders, and movements from the offline store.
 * Returns a snapshot whose `pending` flag reflects unsynced local changes only.
 * // req-8
 * @returns A LocalSnapshot containing the locally persisted entities.
 */
function readLocalSnapshot(): LocalSnapshot {
  const db = localDb();
  return {
    products: db.products.slice(),
    orders: db.orders.slice(),
    movements: db.movements.slice(),
    pending: db.pending,
    syncedAt: db.syncedAt,
  };
}

/**
 * Computes the stock badge level for a product relative to its reorder level.
 * Green is strictly above, amber is exactly at, red is strictly below the reorder level.
 * // req-9
 * @param product - The product whose badge is being computed.
 * @returns The StockStatus colour token.
 */
function stockBadgeLevel(product: Product): StockStatus {
  if (product.stockOnHand > product.reorderLevel) {
    return 'green';
  }
  if (product.stockOnHand === product.reorderLevel) {
    return 'amber';
  }
  return 'red';
}

/**
 * Suggests how many units to reorder for a low-stock product, based on the
 * shortfall against the reorder level plus a sensible buffer.
 * // req-7
 * @param product - The low-stock product.
 * @returns The non-negative suggested reorder quantity.
 */
function suggestReorderQuantity(product: Product): number {
  const shortfall: number = product.reorderLevel - product.stockOnHand;
  const buffer: number = Math.ceil(product.reorderLevel / 2);
  const suggested: number = shortfall + buffer;
  return suggested > 0 ? suggested : 1;
}

/**
 * Records a note against a low-stock alert after the user taps "mark reordered".
 * This must NOT change any product stock; only receiving stock does that.
 * // req-7
 * @param alerts - The alert list to update.
 * @param productId - The product whose alert is being marked reordered.
 * @param note - The note persisted against the alert.
 * @returns A new alert list with the alert marked reordered and note attached.
 */
function markReordered(alerts: LowStockAlert[], productId: string, note: string): LowStockAlert[] {
  if (note.trim().length === 0) {
    return alerts.slice();
  }
  return alerts.map(function (alert: LowStockAlert): LowStockAlert {
    if (alert.productId === productId) {
      return {
        productId: alert.productId,
        productName: alert.productName,
        stockOnHand: alert.stockOnHand,
        reorderLevel: alert.reorderLevel,
        suggestedQuantity: alert.suggestedQuantity,
        createdAt: alert.createdAt,
        reordered: true,
        note: note.trim(),
      };
    }
    return {
      productId: alert.productId,
      productName: alert.productName,
      stockOnHand: alert.stockOnHand,
      reorderLevel: alert.reorderLevel,
      suggestedQuantity: alert.suggestedQuantity,
      createdAt: alert.createdAt,
      reordered: alert.reordered,
      note: alert.note,
    };
  });
}

/**
 * Receives stock for a product by writing a positive stock movement and updating
 * local stock. Queues the change for sync and marks it pending.
 * // req-6
 * @param input - The receive request with productId, quantity, and current snapshot.
 * @returns The updated snapshot and the written movement, or a rejection reason.
 */
function receiveStock(input: { productId: string; quantity: number; snapshot: LocalSnapshot }): { ok: boolean; message: string; snapshot: LocalSnapshot; movement: StockMovement | null } {
  const qty: number = input.quantity;
  if (qty <= 0) {
    return { ok: false, message: 'Quantity must be positive.', snapshot: input.snapshot, movement: null };
  }
  const products: Product[] = input.snapshot.products.map(function (p: Product): Product {
    if (p.id === input.productId) {
      return { id: p.id, name: p.name, priceDisplayedPence: p.priceDisplayedPence, stockOnHand: p.stockOnHand + qty, reorderLevel: p.reorderLevel };
    }
    return { id: p.id, name: p.name, priceDisplayedPence: p.priceDisplayedPence, stockOnHand: p.stockOnHand, reorderLevel: p.reorderLevel };
  });
  const movement: StockMovement = {
    id: 'mv-' + input.productId + '-' + String(input.snapshot.movements.length + 1),
    productId: input.productId,
    quantity: qty,
    reason: 'received',
    createdAt: 'local',
    pending: true,
  };
  const movements: StockMovement[] = input.snapshot.movements.slice();
  movements.push(movement);
  const snapshot: LocalSnapshot = {
    products: products,
    orders: input.snapshot.orders.slice(),
    movements: movements,
    pending: true,
    syncedAt: input.snapshot.syncedAt,
  };
  return { ok: true, message: 'Stock received.', snapshot: snapshot, movement: movement };
}

/**
 * Records spoilage for a product by writing a negative stock movement with a
 * required reason, updating local stock. Rejects missing reasons and non-positive
 * quantities so no reasonless movement is ever written.
 * // req-6
 * @param input - The spoilage request with productId, quantity, reason, and snapshot.
 * @returns The updated snapshot and written movement, or a rejection reason.
 */
function recordSpoilage(input: { productId: string; quantity: number; reason: string; snapshot: LocalSnapshot }): { ok: boolean; message: string; snapshot: LocalSnapshot; movement: StockMovement | null } {
  const qty: number = input.quantity;
  if (input.reason.trim().length === 0) {
    return { ok: false, message: 'A spoilage reason is required.', snapshot: input.snapshot, movement: null };
  }
  if (qty <= 0) {
    return { ok: false, message: 'Quantity must be positive.', snapshot: input.snapshot, movement: null };
  }
  const products: Product[] = input.snapshot.products.map(function (p: Product): Product {
    if (p.id === input.productId) {
      const next: number = p.stockOnHand - qty;
      return { id: p.id, name: p.name, priceDisplayedPence: p.priceDisplayedPence, stockOnHand: next < 0 ? 0 : next, reorderLevel: p.reorderLevel };
    }
    return { id: p.id, name: p.name, priceDisplayedPence: p.priceDisplayedPence, stockOnHand: p.stockOnHand, reorderLevel: p.reorderLevel };
  });
  const movement: StockMovement = {
    id: 'mv-' + input.productId + '-' + String(input.snapshot.movements.length + 1),
    productId: input.productId,
    quantity: -qty,
    reason: input.reason.trim(),
    createdAt: 'local',
    pending: true,
  };
  const movements: StockMovement[] = input.snapshot.movements.slice();
  movements.push(movement);
  const snapshot: LocalSnapshot = {
    products: products,
    orders: input.snapshot.orders.slice(),
    movements: movements,
    pending: true,
    syncedAt: input.snapshot.syncedAt,
  };
  return { ok: true, message: 'Spoilage recorded.', snapshot: snapshot, movement: movement };
}

/**
 * Renders the Stock screen model: a searchable product list where each product
 * shows a green, amber, or red badge relative to its reorder level.
 * // req-6
 * @param input - The search term and current snapshot.
 * @returns The filtered product rows with badges and an empty-result flag.
 */
function StockScreen(input: { query: string; snapshot: LocalSnapshot }): { rows: { product: Product; badge: StockStatus }[]; empty: boolean } {
  const q: string = input.query.trim().toLowerCase();
  const rows: { product: Product; badge: StockStatus }[] = [];
  input.snapshot.products.forEach(function (p: Product): void {
    if (q.length === 0 || p.name.toLowerCase().indexOf(q) !== -1) {
      rows.push({ product: p, badge: stockBadgeLevel(p) });
    }
  });
  return { rows: rows, empty: rows.length === 0 };
}
export { readLocalSnapshot, stockBadgeLevel, suggestReorderQuantity, markReordered, receiveStock, recordSpoilage, StockScreen };

